CREATE TABLE COTACOES_NVDA (
    ID INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    DATA_COTACAO DATE NOT NULL,
    TICKER VARCHAR(10) NOT NULL,
    OPEN DECIMAL(20,15) NOT NULL,
    HIGH DECIMAL(20,15) NOT NULL,
    LOW DECIMAL(20,15) NOT NULL,
    CLOSE DECIMAL(20,15) NOT NULL,
    VOLUME BIGINT NOT NULL,
    DAILY_RETURN_PCT DECIMAL(20,15) NULL,
    LOG_RETURN DECIMAL(20,15) NULL,
    INTRADAY_RETURN_PCT DECIMAL(20,15) NOT NULL,
    DAILY_RANGE_PCT DECIMAL(20,15) NOT NULL,
    OVERNIGHT_GAP_PCT DECIMAL(20,15) NULL,
    SMA_20 DECIMAL(20,15) NULL,
    SMA_50 DECIMAL(20,15) NULL,
    VOLATILITY_20_PCT DECIMAL(20,15) NULL,
    VOLUME_SMA_20 BIGINT NULL,
    DRAWDOWN_PCT DECIMAL(20,15) NOT NULL,
    YEAR SMALLINT NOT NULL,
    MONTH TINYINT NOT NULL,
    DAY_OF_WEEK VARCHAR(10) NOT NULL,
    UNIQUE KEY UK_COTACAO_TICKER_DATA (TICKER, DATA_COTACAO)
) ENGINE=INNODB;





